package main

import (
  "database/sql"
  "encoding/json"
  "fmt"
  "log"
  "net/http"

  "github.com/gorilla/mux"
  _ "github.com/lib/pq"
)

type Post struct {
  ID      int    `json:"id"`
  Title   string `json:"title"`
  Content string `json:"content"`
  UserID  int    `json:"user_id"`
}

func main() {
  db, err := sql.Open("postgres", "user=myuser password=mypass dbname=mydb sslmode=disable")
  if err != nil {
    log.Fatal(err)
  }
  defer db.Close()

  router := mux.NewRouter()
  router.HandleFunc("/posts", getPosts).Methods("GET")
  router.HandleFunc("/posts/{id}", getPost).Methods("GET")
  router.HandleFunc("/posts", createPost).Methods("POST")
  router.HandleFunc("/posts/{id}", updatePost).Methods("PUT")
  router.HandleFunc("/posts/{id}", deletePost).Methods("DELETE")

  log.Fatal(http.ListenAndServe(":8080", router))
}

func getPosts(w http.ResponseWriter, r *http.Request) {
  rows, err := db.Query("SELECT * FROM posts")
  if err != nil {
    http.Error(w, err.Error(), http.StatusInternalServerError)
    return
  }
  defer rows.Close()

  var posts []Post
  for rows.Next() {
    var post Post
    err := rows.Scan(&post.ID, &post.Title, &post.Content, &post.UserID)
    if err != nil {
      http.Error(w, err.Error(), http.StatusInternalServerError)
      return
    }
    posts = append(posts, post)
  }

  json.NewEncoder(w).Encode(posts)
}

func getPost(w http.ResponseWriter, r *http.Request) {
  vars := mux.Vars(r)
  id := vars["id"]

  row := db.QueryRow("SELECT * FROM posts WHERE id = $1", id)
  var post Post
  err := row.Scan(&post.ID, &post.Title, &post.Content, &post.UserID)
  if err != nil {
    http.Error(w, err.Error(), http.StatusNotFound)
    return
  }

  json.NewEncoder(w).Encode(post)
}

func createPost(w http.ResponseWriter, r *http.Request) {
  var post Post
  err := json.NewDecoder(r.Body).Decode(&post)
  if err != nil {
    http.Error(w, err.Error(), http.StatusBadRequest)
    return
  }

  _, err = db.Exec("INSERT INTO posts (title, content, user_id) VALUES ($1, $2, $3)", post.Title, post.Content, post.UserID)
  if err != nil {
    http.Error(w, err.Error(), http.StatusInternalServerError)
    return
  }

  json.NewEncoder(w).Encode(post)
}

func updatePost(w http.ResponseWriter, r *http.Request) {
